$('estimateLines').addEventListener('input',refreshEstimate);$('estimateLines').addEventListener('change',refreshEstimate);$('estimateLines').addEventListener('click',e=>{if(e.target.closest('.est-remove')){e.target.closest('tr').remove();refreshEstimate()}});
